412	func getRSSHeading(ctx context.Context, stores *store.Store) (RSSHeading, error) {
413		settings, err := stores.GetInstanceGeneralSetting(ctx)
414		if err != nil {
415			return RSSHeading{}, err
416		}
417		if settings == nil || settings.CustomProfile == nil {
418			return RSSHeading{
419				Title:       "Memos",
420				Description: "An open source, lightweight note-taking service. Easily capture and share your great thoughts.",
421				Language:    "en-us",
422			}, nil
423		}
424		customProfile := settings.CustomProfile
425	
426		return RSSHeading{
427			Title:       customProfile.Title,
428			Description: customProfile.Description,
429			Language:    "en-us",
430		}, nil
431	}
