16	func (s *APIV1Service) touchMemoUpdatedTimestamp(ctx context.Context, memoID int32) error {
17		updatedTs := time.Now().Unix()
18		if err := s.Store.UpdateMemo(ctx, &store.UpdateMemo{
19			ID:        memoID,
20			UpdatedTs: &updatedTs,
21		}); err != nil {
22			return status.Errorf(codes.Internal, "failed to update memo timestamp")
23		}
24		return nil
25	}
26	
27	func (s *APIV1Service) buildUpdatedMemoState(ctx context.Context, memoID int32) (*store.Memo, *store.Memo, *v1pb.Memo, error) {
28		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &memoID})
29		if err != nil {
30			return nil, nil, nil, errors.Wrap(err, "failed to get memo")
31		}
32		if memo == nil {
33			return nil, nil, nil, errors.New("memo not found")
34		}
35	
36		memoName := buildMemoName(memo.UID)
37		reactions, err := s.Store.ListReactions(ctx, &store.FindReaction{
38			ContentID: &memoName,
39		})
40		if err != nil {
41			return nil, nil, nil, errors.Wrap(err, "failed to list reactions")
42		}
43		attachments, err := s.Store.ListAttachments(ctx, &store.FindAttachment{
44			MemoID: &memo.ID,
45		})
46		if err != nil {
47			return nil, nil, nil, errors.Wrap(err, "failed to list attachments")
48		}
49		relations, err := s.loadMemoRelations(ctx, memo)
50		if err != nil {
51			return nil, nil, nil, errors.Wrap(err, "failed to load memo relations")
52		}
53		memoMessage, err := s.convertMemoFromStore(ctx, memo, reactions, attachments, relations)
54		if err != nil {
55			return nil, nil, nil, errors.Wrap(err, "failed to convert memo")
56		}
57	
58		var parentMemo *store.Memo
59		if memo.ParentUID != nil {
60			parentMemo, _ = s.Store.GetMemo(ctx, &store.FindMemo{UID: memo.ParentUID})
61		}
62	
63		return memo, parentMemo, memoMessage, nil
64	}
65	
66	func (s *APIV1Service) dispatchMemoUpdatedSideEffects(ctx context.Context, memo *store.Memo, parentMemo *store.Memo, memoMessage *v1pb.Memo) {
67		if err := s.DispatchMemoUpdatedWebhook(ctx, memoMessage); err != nil {
68			slog.Warn("Failed to dispatch memo updated webhook", slog.Any("err", err))
69		}
70	
71		s.SSEHub.Broadcast(&SSEEvent{
72			Type:       SSEEventMemoUpdated,
73			Name:       memoMessage.Name,
74			Parent:     memoMessage.GetParent(),
75			Visibility: memo.Visibility,
76			CreatorID:  resolveSSECreatorID(memo, parentMemo),
77		})
78	}
